from itertools import product, combinations
import heapq


def _dependency_solver(preference, name_order, feature_filter=True):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        active = {}
        for name, rows in packages.items():
            active[name] = {}
            for row in rows:
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and (not feature_filter or feature not in features):
                        continue
                    deps.append(dep)
                active[name][row["version"]] = deps

        choices = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            choices.append([-1] + versions)

        best_vector = None
        best = None
        order = sorted(names, reverse=(name_order == "descending"))
        want_max = preference == "maximum"
        for vals in product(*choices):
            selected = dict(zip(names, vals))
            installed = {n for n, v in selected.items() if v != -1}
            good = True
            for name, bounds in roots.items():
                version = selected[name]
                if version == -1 or not bounds[0] <= version <= bounds[1]:
                    good = False
                    break
            if not good:
                continue

            edges = {}
            for name in installed:
                deps = active[name][selected[name]]
                edges[name] = []
                for dep in deps:
                    other = dep["name"]
                    version = selected[other]
                    if version == -1 or not dep["min"] <= version <= dep["max"]:
                        good = False
                        break
                    edges[name].append(other)
                if not good:
                    break
            if not good:
                continue

            closure = set()
            todo = list(roots)
            while todo:
                name = todo.pop()
                if name in closure:
                    continue
                closure.add(name)
                todo.extend(edges.get(name, []))
            if closure != installed:
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                state[name] = 2
                return True
            if not all(visit(name) for name in installed):
                continue

            vector = tuple(selected[name] for name in order)
            if best_vector is None or (vector > best_vector if want_max else vector < best_vector):
                best_vector = vector
                best = {n: selected[n] for n in names if selected[n] != -1}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        return n // d if mode == "floor" else (2 * n + d) // (2 * d)

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    allowed = [job for job in jobs if job["id"] not in blocked]
    for subset in combinations(allowed, k):
        ids = [job["id"] for job in subset]
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start = (data["start"], start_node, start_mask, 0)
    distances = {(start_node, start_mask, 0): data["start"]}
    queue = [start]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and spent == data["coupons"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], spent)]
            if spent < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, spent + 1))
            for duration, next_spent in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_spent)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_spent))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency_solver("minimum", "descending"),
    "component_02": _dependency_solver("maximum", "ascending", False),
    "component_03": _dependency_solver("minimum", "ascending"),
    "component_04": _dependency_solver("maximum", "descending"),
    "component_05": _dependency_solver("minimum", "descending", False),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}

